package com.novasoft.psicoapp.model; import jakarta.persistence.*; import java.time.*;
@Entity public class Submission{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne public Assignment assignment; @ManyToOne public User student; @Column(length=5000) public String analysisText; public String status="BORRADOR"; public int autoScore=0; public Double grade; @Column(length=2500) public String feedback; public LocalDateTime updatedAt=LocalDateTime.now(); public LocalDateTime submittedAt; }
